let otherExtrasFlds = ["AID","REF #","TRANS ID","APPROVAL", "OP#", "ST#", "TC", "TERMINAL #"]

export const parseTextExpenses = (txt,  cb) => {
    
    let lineText = {
        description:"",
        document:"",
        title:"",
        amount: 0
     };
   
     let otherExta = {
        
     };

     let namesTitles = [];

    txt && txt.map((arrayText, ind2)=>{
        
        arrayText?.SummaryFields && arrayText?.SummaryFields.map((dd, ind2)=>{

           
            let type = dd?.Type?.Text;
            let key = dd?.LabelDetection?.Text;
            let value = dd?.ValueDetection?.Text;

            if(type === "OTHER"){
                otherExta[key] = value;
            }

            if(type === "TOTAL"){
                lineText["amount"] = value*1;
            }

            if(type === "VENDOR_NAME"){
                namesTitles.push(value)
            }

            if(type === "NAME"){
                namesTitles.push(value)
            }
        }); 
    });

    otherExtrasFlds.map(fld=>{
        if(otherExta[fld]){
            lineText.description += fld+ " " + otherExta[fld] + "; "
        }
    })
    namesTitles.map(nmI=>{
        lineText.title += "" + nmI + "; "
    })

    if(lineText.title.indexOf("almart")>=0){
        if(otherExta["TC#"]){
            lineText.document = "TC# " + otherExta["TC#"];        }
    }
    return lineText;

}





